style.css:
@-moz-document domain("chatgpt.com"), domain("platform.openai.com") {
:root {
    --codex-accent: var(--accent);
    --codex-accent-source: chatgpt;
    --codex-ink: var(--ink);
    --codex-surface: var(--surface);
    --codex-contrast: 60;
    --codex-diff-added: var(--diffAdded);
    --codex-diff-removed: var(--diffRemoved);
    --codex-skill: var(--skill);
    --codex-opaque-windows: 1;
  }

  /* ---------- Base surfaces ---------- */
  html, body {
    background-color: var(--codex-surface) !important;
    color: #e6e6e6 !important;
    font-family: "Space Grotesk", "Roboto Mono", system-ui, sans-serif !important;
  }

  /* Main app shell */
  main, [role="main"], .app-wrapper, .chat-container {
    background-color: var(--codex-surface) !important;
    color: #e6e6e6 !important;
  }

  /* ---------- Accent elements ---------- */
  a, button.primary, .btn-primary, [data-accent] {
    color: var(--codex-accent) !important;
  }

  button, .button {
    border-color: var(--codex-accent) !important;
  }

  /* Focus rings */
  :focus-visible {
    outline: 2px solid var(--codex-accent) !important;
    outline-offset: 2px !important;
  }

  /* ---------- Ink / text accent ---------- */
  h1, h2, h3, .title, .heading {
    color: var(--codex-ink) !important;
  }

  /* ---------- Scrollbars ---------- */
  ::-webkit-scrollbar {
    width: 10px;
    height: 10px;
  }

  ::-webkit-scrollbar-track {
    background: #0a0a0a;
  }

  ::-webkit-scrollbar-thumb {
    background: #2a2a2a;
    border-radius: 6px;
  }

  ::-webkit-scrollbar-thumb:hover {
    background: var(--codex-accent);
  }

  /* ---------- Code blocks & diffs ---------- */
  pre, code, .code-block {
    background-color: #0d0d0d !important;
    border: 1px solid #1f1f1f !important;
    color: #e6e6e6 !important;
    border-radius: 8px !important;
  }

  /* Diff: added */
  .diff-added, .line-added, [data-diff="added"], .addition {
    background-color: rgba(64, 201, 119, 0.12) !important;
    color: var(--codex-diff-added) !important;
    border-left: 3px solid var(--codex-diff-added) !important;
  }

  /* Diff: removed */
  .diff-removed, .line-removed, [data-diff="removed"], .deletion {
    background-color: rgba(250, 66, 62, 0.12) !important;
    color: var(--codex-diff-removed) !important;
    border-left: 3px solid var(--codex-diff-removed) !important;
  }

  /* Skill highlight */
  .skill, .skill-badge, [data-skill] {
    color: var(--codex-skill) !important;
    border-color: var(--codex-skill) !important;
  }

  /* ---------- Inputs ---------- */
  input, textarea, select {
    background-color: #0a0a0a !important;
    color: #e6e6e6 !important;
    border: 1px solid #2a2a2a !important;
    border-radius: 6px !important;
  }

  input:focus, textarea:focus, select:focus {
    border-color: var(--codex-accent) !important;
    box-shadow: 0 0 0 2px rgba(83, 181, 89, 0.25) !important;
  }

  /* ---------- Cards / panels ---------- */
  .card, .panel, .modal, [role="dialog"] {
    background-color: #0a0a0a !important;
    border: 1px solid #1f1f1f !important;
    border-radius: 12px !important;
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.6) !important;
  }

  /* ---------- Opaque windows ---------- */
  .window, .overlay {
    backdrop-filter: none !important;
    background-color: #000000 !important;
  }

  /* ---------- Selection ---------- */
  ::selection {
    background-color: var(--codex-accent) !important;
    color: #000000 !important;
  }

  /* ---------- Reduced motion ---------- */
  @media (prefers-reduced-motion: reduce) {
    *, *::before, *::after {
      animation: none !important;
      transition: none !important;
    }
  }
}
